export const fixtureBytes = {"large":{"type":"image/png","data":""},"png":{"type":"image/png","data":""},"jpeg":{"type":"image/jpeg","data":""},"webp":{"type":"image/webp","data":""},"apng":{"type":"image/png","data":""},"animatedWebp":{"type":"image/webp","data":""},"corrupt":{"type":"image/png","data":"iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAIAAACQkWg2AAAAEUlEQVRub3QtYS16bGliLXN0cmVhbQ2CzCQAAAAASUVORK5CYII="}}
export function fixtureBlob(name) { const f = fixtureBytes[name]; return new Blob([Uint8Array.from(atob(f.data), c => c.charCodeAt(0))], { type: f.type }) }
